class DynamicArray {
    int* ptr;
public:
    explicit DynamicArray(size_t s) : ptr(new int[s]) {}

    // Resource is released automatically when object is destroyed
    ~DynamicArray() { delete[] ptr; } 

    // RAII objects should usually not be copied
    DynamicArray(const DynamicArray&) = delete;
    DynamicArray& operator=(const DynamicArray&) = delete;
};
void use_array() {
    DynamicArray arr(10);
    // arr uses resource...
} // arr destroyed, memory safely freed.


